from nltk.tokenize import PunktSentenceTokenizer
#%% sentence tokenizer
def sentence_tokenizer(input_text):
    sent_detector = PunktSentenceTokenizer()
    output_list = sent_detector.tokenize(input_text)
    print('\n-----\n'.join(output_list))
    return output_list

